//------------------------------------------------------------------------------
// test_runtime.cpp -- runtime initialization sequence audit (il2cpp_runtime_init).
//
// Pins the RUNTIME half of the startup contract. The public C API entry
// (il2cpp_runtime_init) is GENERATED by the transpiler in entry.cpp; its first
// call is il2cpp::runtime::runtime_init() (runtime.cpp), which MUST leave the
// runtime's own global state fully usable before the generated init proceeds
// to the per-assembly registrations (string pool fill -> resource pool fill ->
// type registration -> Main .cctor). This test verifies:
//
//   1. runtime_init() is idempotent (the C API contract: "call once before any
//      other API", and the repeated-init path must not crash -- the generated
//      il2cpp_runtime_init is itself re-entrant-safe, capi/main.cpp).
//   2. After runtime_init(), the GC heap is usable: a managed allocation is
//      non-null, zero-initialized and klass-stamped (the collector bootstrap
//      ran -- no lazy-init gap).
//   3. After runtime_init(), the type registry is usable: il2cpp_class_register
//      + il2cpp_class_by_name round-trip (the type table the generated init
//      fills next).
//   4. RES wiring (il2cpp_resources_register, the target of the generated
//      resource-pool.h il2cpp_resource_pool_fill): register + query works
//      after init (Assembly.GetManifestResourceNames surface).
//   5. String-pool wiring (il2cpp_string_intern_literal, the target of the
//      generated string-pool.h il2cpp_string_pool_fill): intern after init.
//   6. Thread-local: the MAIN thread reports NOT a ThreadPool worker (the
//      thread_local registration default; pool workers set the flag at entry).
//
// Plain executable + minimal assertion harness (see test_object.cpp).
//------------------------------------------------------------------------------

#include "il2cpp_runtime.h"
#include "il2cpp_resources.h"
#include "il2cpp_streamio.h"
#include "il2cpp_string_intern.h"
#include "il2cpp_thread.h"

#include <cstdint>
#include <cstdio>
#include <cstring>

using namespace il2cpp; // unqualified Il2Cpp* types (test_io.cpp convention)

namespace {

int g_failures = 0;

void Expect(bool condition, const char* what)
{
    if (!condition)
    {
        std::printf("FAIL: %s\n", what);
        ++g_failures;
    }
}

// Mock descriptor for the allocation + registry checks (test_object.cpp
// convention): a 16-byte payload, no reference fields.
Il2CppClass g_mockClass = {
    "Test.RuntimeInitMock", // name
    24,                     // instanceSize: header + 2 payload slots (24B)
    0u,                     // refFieldBitmap: no reference fields
    0,                      // refFieldCount
    nullptr,                // baseClass: standalone fixture
    nullptr,                // vtable: no virtuals
    0,                      // vtableSize
    nullptr,                // interfaces: none
    0,                      // interfaceCount
};

} // namespace

int main()
{
    // --- 1. runtime_init() completes and is idempotent ----------------------
    il2cpp::runtime::runtime_init();
    Expect(true, "runtime_init() completes");
    il2cpp::runtime::runtime_init();
    Expect(true, "repeated runtime_init() does not crash (idempotent)");

    // --- 2. GC heap usable after init (collector bootstrap ran) -------------
    Il2CppObject* obj = il2cpp_object_new(&g_mockClass);
    Expect(obj != nullptr, "allocation after runtime_init() returns non-null");
    Expect(obj->klass == &g_mockClass, "allocated object klass header is stamped");
    {
        // Zero-init: the payload region (after the klass header) is all zeros.
        const unsigned char* bytes = static_cast<const unsigned char*>(static_cast<const void*>(obj));
        bool zero = true;
        for (size_t i = sizeof(Il2CppObject); i < static_cast<size_t>(g_mockClass.instanceSize); ++i)
        {
            if (bytes[i] != 0)
            {
                zero = false;
            }
        }
        Expect(zero, "allocated object payload is zero-initialized after init");
    }

    // --- 3. Type registry usable after init ---------------------------------
    il2cpp_class_register(&g_mockClass);
    Expect(il2cpp_class_by_name("Test.RuntimeInitMock") == &g_mockClass,
           "il2cpp_class_register + il2cpp_class_by_name round-trip after init");

    // --- 4. RES wiring: the generated resource-pool fill target works -------
    // il2cpp_resource_pool_fill() (emitted in resource-pool.h) calls
    // il2cpp_resources_register; the Assembly surface then queries the table.
    const uint8_t payload[] = { 0x48, 0x49 }; // "HI"
    const ManifestResourceEntry kPool[] = {
        { "runtime-init.bin", payload, static_cast<int32_t>(sizeof(payload)) },
    };
    il2cpp_resources_register(kPool, 1);

    Il2CppObject* names = il2cpp_assembly_get_manifest_resource_names();
    Expect(names != nullptr, "GetManifestResourceNames after register returns a string[]");
    if (names != nullptr)
    {
        Il2CppArray* namesArr = reinterpret_cast<Il2CppArray*>(names);
        Expect(namesArr->length == 1, "registered resource appears in the names array");
    }
    Il2CppObject* stream = il2cpp_assembly_get_manifest_resource_stream(
        reinterpret_cast<Il2CppObject*>(il2cpp_string_new_from_utf8("runtime-init.bin")));
    Expect(stream != nullptr, "GetManifestResourceStream resolves the registered payload");
    if (stream != nullptr)
    {
        // GetManifestResourceStream returns a MemoryStream OBJECT (batch 90
        // contract -- net48: the manifest stream IS a Stream), not a raw
        // byte[]; ToArray() round-trips the payload back for comparison.
        const Il2CppArray* arr = il2cpp::runtime::icall_stream_memory_to_array(stream);
        Expect(arr != nullptr && arr->length == static_cast<int32_t>(sizeof(payload))
                   && std::memcmp(arr->data, payload, sizeof(payload)) == 0,
               "resource stream content matches the registered payload");
    }

    // --- 5. String-pool wiring: the generated string-pool fill target -------
    Il2CppObject* interned = il2cpp_string_intern_literal("runtime-init-literal");
    Expect(interned != nullptr, "il2cpp_string_intern_literal after init returns non-null");

    // --- 6. Thread-local: main thread is NOT a pool worker ------------------
    Expect(!il2cpp::runtime::il2cpp_threadpool_is_current_thread_worker(),
           "main thread reports NOT a ThreadPool worker (thread_local default)");

    // --- 7. Builtin System.* registration contract (str_concat perf regress) -
    // Every builtin descriptor must resolve after a single ensure call, and
    // repeated ensure calls (what every string allocation used to pay for) must
    // stay idempotent -- the once-guard keeps the registry identical while
    // removing the per-allocation linear re-scan (bench v7: 0.81 -> 0.65).
    il2cpp_ensure_builtin_system_classes();
    const char* kBuiltinNames[] = {
        "System.Object",
        "System.String",
        "System.Int32",
        "System.UInt32",
        "System.Boolean",
        "System.Char",
        "System.Double",
        "System.IConvertible",
        "System.IComparable",
        "System.IFormattable",
        "System.Collections.Generic.Dictionary`2<string,int>",
        "System.Resources.ResourceManager",
        "System.Globalization.CultureInfo",
    };
    for (const char* name : kBuiltinNames)
    {
        Expect(il2cpp_class_by_name(name) != nullptr,
               "ensure registers every builtin descriptor for lookup");
    }
    // The real regression shape: ensure runs once per string allocation. A
    // repeat burst (surrogate for the 500K-allocation str_concat loop) must not
    // crash, grow the registry, or lose the registrations.
    for (int i = 0; i < 1000; ++i)
    {
        il2cpp_ensure_builtin_system_classes();
    }
    Expect(il2cpp_class_by_name("System.String") == &System_String_class,
           "repeated ensure keeps System.String registered at its descriptor");
    Expect(il2cpp_class_by_name("System.Object") == &System_Object_class,
           "repeated ensure keeps System.Object registered at its descriptor");

    if (g_failures == 0)
    {
        std::printf("all runtime init sequence tests passed\n");
        return 0;
    }
    std::printf("%d runtime init sequence test(s) FAILED\n", g_failures);
    return 1;
}
